def solve(s):
    n = len(s)
    if n == 0:
        return ''
    best_start, best_len = 0, 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - l - 1
    for i in range(n):
        for (l, r) in ((i, i), (i, i + 1)):
            st, ln = expand(l, r)
            if ln > best_len or (ln == best_len and st < best_start):
                best_start, best_len = st, ln
    return s[best_start:best_start + best_len]

