def solve(intervals):
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda x: x[0])
    res = [list(ivs[0])]
    for s, e in ivs[1:]:
        if s <= res[-1][1]:
            if e > res[-1][1]:
                res[-1][1] = e
        else:
            res.append([s, e])
    return res

